 public void RefreshMenus(){if(hud==null)return;bool open=S.Menu!=FestivalMenu.None;hud.gameObject.SetActive(!open);menus.gameObject.SetActive(open);menuBackdrop.raycastTarget=S.Menu!=FestivalMenu.Photo;menuBackdrop.color=S.Menu==FestivalMenu.Garage||S.Menu==FestivalMenu.Photo?Color.clear:new Color(Ink.r,Ink.g,Ink.b,.965f);foreach(var root in menuRoots)root.SetActive(false);GameObject active=S.Menu switch{FestivalMenu.Events=>eventsPanel,FestivalMenu.Garage=>garagePanel,FestivalMenu.Map=>mapPanel,FestivalMenu.Pause=>pausePanel,FestivalMenu.Results=>resultPanel,FestivalMenu.Radio=>radioPanel,FestivalMenu.Photo=>photoPanel,_=>null};if(active)active.SetActive(true);RefreshPhoto();if(S.Menu==FestivalMenu.Garage)RefreshGarage();if(S.Menu==FestivalMenu.Results){resultTitle.text=S.ResultMedal;resultTime.text=FestivalSession.Clock(S.RaceTime);resultReward.text="+"+S.ResultReward.ToString("N0")+" CR";resultDetails.text="POSITION "+S.RacePlace+" / 4\n"+(S.PersonalBest?"NEW PERSONAL BEST":"BEST  "+FestivalSession.Clock(S.BestTime(S.EventIndex)));}if(mapGarageButton)mapGarageButton.interactable=S.State==FestivalRace.Cruise;if(exploredLabel)exploredLabel.text="DISCOVERED "+S.Discoveries+" / "+S.TotalDiscoveries+"  /  "+S.Credits.ToString("N0")+" CR";}
