 void Reflow(){var bounds=((RectTransform)canvas.transform).rect;if(lastCanvasSize==bounds.size&&lastLayoutRace==S.RaceActive)return;lastCanvasSize=bounds.size;lastLayoutRace=S.RaceActive;menuStage.localScale=Vector3.one*Mathf.Min(bounds.width/1920f,bounds.height/1080f);bool narrow=bounds.width<1780,racing=S.RaceActive;((RectTransform)raceRoot.transform).anchoredPosition=new Vector2(-366,narrow?-180:-35);checkpointDistance.rectTransform.anchoredPosition=new Vector2(-310,narrow?-308:-170);((RectTransform)noticeRoot.transform).anchoredPosition=new Vector2(-330,narrow&&racing?-353:-204);}
 RectTransform Marker(Transform parent,float size,Color color,bool arrow){var r=Rect(parent,arrow?"Your position":"Next gate",0,0,size,size);r.pivot=new Vector2(.5f,.5f);var im=Image(r,color);if(arrow){im.sprite=ArrowSprite();}else im.sprite=ringSprite;return r;}
 void PlaceMarker(RectTransform r,Vector3 p,float size,bool rotate){var uv=MapUV(p);r.anchoredPosition=new Vector2(uv.x*size,-(1-uv.y)*size);if(rotate)r.localRotation=Quaternion.Euler(0,0,-S.Game.Player.transform.eulerAngles.y);}
 Vector2 MapUV(Vector3 p)=>new(Mathf.Clamp01((p.x-mapMin.x)/(mapMax.x-mapMin.x)),Mathf.Clamp01((p.z-mapMin.y)/(mapMax.y-mapMin.y)));
 void DrawLandmarks(Transform p,float size,float markerSize){for(int i=0;i<S.Game.World.Landmarks.Count;i++){var landmark=S.Game.World.Landmarks[i];var uv=MapUV(landmark.Position);var icon=Box(p,landmark.Name,uv.x*size-markerSize*.5f,(1-uv.y)*size-markerSize*.5f,markerSize,markerSize,landmark.Color);icon.sprite=dotSprite;}}
 void BuildMapTexture(){const int size=640;mapMin=new Vector2(float.MaxValue,float.MaxValue);mapMax=new Vector2(float.MinValue,float.MinValue);foreach(var road in S.Game.World.Roads)foreach(var p in road.Points){mapMin=Vector2.Min(mapMin,new Vector2(p.x,p.z));mapMax=Vector2.Max(mapMax,new Vector2(p.x,p.z));}Vector2 center=(mapMin+mapMax)*.5f;float extent=Mathf.Max(mapMax.x-mapMin.x,mapMax.y-mapMin.y)*.55f+90;mapMin=center-Vector2.one*extent;mapMax=center+Vector2.one*extent;mapTexture=new Texture2D(size,size,TextureFormat.RGBA32,false){name="Sunward discovery atlas",filterMode=FilterMode.Bilinear};var pixels=new Color32[size*size];
  for(int y=0;y<size;y++)for(int x=0;x<size;x++){float wx=Mathf.Lerp(mapMin.x,mapMax.x,x/(float)(size-1)),wz=Mathf.Lerp(mapMin.y,mapMax.y,y/(float)(size-1));float h=S.Game.World.GroundHeight(wx,wz);float shade=Mathf.Clamp01(h/90);Color c=h<0?new Color(.047f,.13f,.17f):Color.Lerp(new Color(.095f,.20f,.20f),new Color(.19f,.29f,.25f),shade);if(x%64==0||y%64==0)c=Color.Lerp(c,Cream,.035f);pixels[y*size+x]=c;}
  foreach(var road in S.Game.World.Roads){Color col=road.MapColor;for(int i=1;i<road.Points.Length;i++){Vector2 a=MapUV(road.Points[i-1])*(size-1),b=MapUV(road.Points[i])*(size-1);DrawLine(pixels,size,a,b,new Color(.025f,.075f,.09f),6);}}foreach(var road in S.Game.World.Roads){for(int i=1;i<road.Points.Length;i++){Vector2 a=MapUV(road.Points[i-1])*(size-1),b=MapUV(road.Points[i])*(size-1);DrawLine(pixels,size,a,b,Color.Lerp(road.MapColor,Cream,.55f),3);}}
  mapTexture.SetPixels32(pixels);mapTexture.Apply(false,true);
 }
 static void DrawLine(Color32[] pixels,int size,Vector2 a,Vector2 b,Color color,int radius){int steps=Mathf.CeilToInt(Vector2.Distance(a,b)*1.4f);for(int i=0;i<=steps;i++){Vector2 p=Vector2.Lerp(a,b,steps==0?0:i/(float)steps);int cx=Mathf.RoundToInt(p.x),cy=Mathf.RoundToInt(p.y);for(int y=-radius;y<=radius;y++)for(int x=-radius;x<=radius;x++){int px=cx+x,py=cy+y;if(px>=0&&py>=0&&px<size&&py<size&&x*x+y*y<=radius*radius)pixels[py*size+px]=color;}}}
 void MiniRoute(Transform p,RoadPath road,float x,float y,float w,float h,Color color){Vector2 min=new(float.MaxValue,float.MaxValue),max=new(float.MinValue,float.MinValue);foreach(var pos in road.Points){min=Vector2.Min(min,new Vector2(pos.x,pos.z));max=Vector2.Max(max,new Vector2(pos.x,pos.z));}float scale=Mathf.Min((w-20)/Mathf.Max(1,max.x-min.x),(h-20)/Mathf.Max(1,max.y-min.y));Vector2 offset=new Vector2(x+w*.5f,y+h*.5f)-(min+max)*.5f*scale;for(int i=1;i<road.Points.Length;i++){Vector2 a=new(road.Points[i-1].x,road.Points[i-1].z),b=new(road.Points[i].x,road.Points[i].z);a=a*scale+offset;b=b*scale+offset;var line=Box(p,"Road trace",a.x,y+h-(a.y-y),Vector2.Distance(a,b)+1,3,color);line.rectTransform.pivot=new Vector2(0,.5f);line.rectTransform.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(b.y-a.y,b.x-a.x)*Mathf.Rad2Deg);}}
 Sprite Shape(bool ring,bool circle){const int n=64;var texture=new Texture2D(n,n,TextureFormat.RGBA32,false){name=ring?"Instrument ring":"Interface shape",filterMode=FilterMode.Bilinear};var pixels=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float distance=Vector2.Distance(new Vector2(x+.5f,y+.5f),new Vector2(32,32));float alpha;if(ring)alpha=Mathf.Clamp01(32-distance)*Mathf.Clamp01(distance-27);else if(circle)alpha=Mathf.Clamp01(32-distance);else{Vector2 q=new Vector2(Mathf.Abs(x-31.5f),Mathf.Abs(y-31.5f))-Vector2.one*20;float d=new Vector2(Mathf.Max(0,q.x),Mathf.Max(0,q.y)).magnitude+Mathf.Min(Mathf.Max(q.x,q.y),0)-11;alpha=Mathf.Clamp01(-d);}pixels[y*n+x]=new Color(1,1,1,alpha);}texture.SetPixels(pixels);texture.Apply(false,true);return Sprite.Create(texture,new UnityEngine.Rect(0,0,n,n),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(16,16,16,16));}
 Sprite arrowSprite;Sprite ArrowSprite(){if(arrowSprite)return arrowSprite;const int n=32;var texture=new Texture2D(n,n,TextureFormat.RGBA32,false){name="Player compass arrow",filterMode=FilterMode.Bilinear};var pixels=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float py=y/(float)n,dx=Mathf.Abs((x+.5f)/n-.5f);bool on=dx<(.5f*(1-py))&&py>.15f+dx*.35f;pixels[y*n+x]=new Color(1,1,1,on?1:0);}texture.SetPixels(pixels);texture.Apply(false,true);arrowSprite=Sprite.Create(texture,new UnityEngine.Rect(0,0,n,n),new Vector2(.5f,.5f));return arrowSprite;}
